    [('3.3 s', '@Timeout(1) 的忙等测试(不检查中断)整个 JVM 的用时,超时只是把它判为失败'), ('null', '@Timeout 的 SEPARATE_THREAD 模式下读到的 ThreadLocal 值(SAME_THREAD 读到的是设置的值)'), ('292–296 / 300', '60 ms 超时在 40 个空转进程的满载机器上失败的次数(空闲机器 0 次)')],
    [('默认的中断超时', None), ('SEPARATE_THREAD', None), ('assertTimeout', None), ('全局默认超时', None), ('超时与机器负载', None)],
